package com.mahweb.mahyarnfc.omnishare.lan;
import com.mahweb.mahyarnfc.omnishare.crypto.CryptoEnvelope; import java.io.*;
public final class SecurePacketCodec { private SecurePacketCodec(){} public static byte[] encode(CryptoEnvelope e){try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeByte(e.nonce.length);d.write(e.nonce);d.writeInt(e.ciphertext.length);d.write(e.ciphertext);d.flush();return b.toByteArray();}catch(IOException x){throw new IllegalStateException(x);}} public static CryptoEnvelope decode(byte[]x)throws IOException{DataInputStream d=new DataInputStream(new ByteArrayInputStream(x));int n=d.readUnsignedByte();if(n!=12)throw new IOException("invalid GCM nonce");byte[]iv=new byte[n];d.readFully(iv);int c=d.readInt();if(c<16||c>65536)throw new IOException("invalid ciphertext length");byte[]ct=new byte[c];d.readFully(ct);if(d.available()!=0)throw new IOException("invalid secure packet");return new CryptoEnvelope(iv,ct);} }
